const MODULES = [
  ["overview", "Overview", "mdi:view-dashboard-outline"],
  ["areas", "Areas", "mdi:home-outline"],
  ["zones", "Zones", "mdi:map-marker-outline"],
  ["labels", "Labels", "mdi:tag-outline"],
  ["categories", "Categories", "mdi:shape-outline"],
  ["entity_ids", "Entity IDs", "mdi:identifier"],
  ["exposed", "Exposed & Aliases", "mdi:account-voice"],
  ["settings", "Settings", "mdi:cog-outline"],
];
const BUILD_TIME = "__HA_ORGANIZER_BUILD_TIME__";
const DEV_BUILD_STAMP = BUILD_TIME.startsWith("20");

class HaOrganizer extends HTMLElement {
  set hass(value) {
    this._hass = value;
    this.toggleAttribute("dark-mode", Boolean(value?.themes?.darkMode));
    if (!this._ready) this.render();
  }

  set panel(value) {
    this._config = value || {};
  }

  async call(type, payload = {}) {
    return this._hass.callWS({ type, ...payload });
  }

  async render() {
    this._ready = true;
    this.innerHTML = `<style>${CSS}${EXTRA_CSS}${UI_CSS}${CATEGORY_CSS}${POLICY_CSS}${ZONE_CSS}${EXPOSED_CSS}${LINK_CSS}${THEME_CSS}</style>
      <div class="app-shell">
        <aside class="sidebar">
          <div class="brand"><img class="brand-mark" src="/ha_organizer/icon.png" alt="HA Organizer"><div><b>HA Organizer</b><small>Organization, under control</small></div></div>
          <div class="nav-label">NAVIGATION</div><button class="sidebar-toggle" id="sidebar-toggle" aria-label="Collapse sidebar">‹</button>
          <nav>${MODULES.map(([id, label, icon]) => `<button class="nav-item" data-module="${id}"><i><ha-icon icon="${icon}"></ha-icon></i><span>${label}</span></button>`).join("")}</nav>
          <div class="sidebar-footer"><span class="pulse"></span> Read-only<small>Version 2026.8.0</small>${DEV_BUILD_STAMP ? `<small class="build-stamp">Copied ${BUILD_TIME}</small>` : ""}</div>
        </aside>
        <section class="workspace">
          <header class="topbar"><div class="mobile-brand"><img class="brand-mark" src="/ha_organizer/icon.png" alt="HA Organizer"><b>HA Organizer</b></div><div class="top-actions"><span class="last-scan">Local audit</span><button class="refresh" id="scan"><span>↻</span> Refresh analysis</button></div></header>
          <main id="content"><div class="loading"><span class="spinner"></span> Preparing your audit…</div></main>
        </section>
      </div>`;
    this.querySelectorAll(".nav-item").forEach((button) => {
      button.onclick = () => this.show(button.dataset.module);
    });
    this.querySelector("#sidebar-toggle").onclick = () => {
      this.classList.toggle("sidebar-collapsed");
      this.querySelector("#sidebar-toggle").textContent = this.classList.contains("sidebar-collapsed") ? "›" : "‹";
    };
    this.querySelector("#scan").onclick = async () => {
      const button = this.querySelector("#scan");
      button.disabled = true;
      button.classList.add("busy");
      try { await this.call("ha_organizer/scan"); await this.show(this._module || "overview"); }
      catch (error) { this.showError(error); }
      finally { button.disabled = false; button.classList.remove("busy"); }
    };
    await this.show("overview");
  }

  setActive(module) {
    this.querySelectorAll(".nav-item").forEach((button) => button.classList.toggle("active", button.dataset.module === module));
  }

  localize() {
    const translations = [
      ["NAVEGAÇÃO", "NAVIGATION"], ["Auditoria local", "Local audit"], ["Atualizar análise", "Refresh analysis"], ["Atualizar", "Refresh"], ["MÓDULO", "MODULE"], ["itens encontrados", "items found"], ["pedem atenção", "need attention"], ["configuradas", "configured"], ["precisam de atenção", "need attention"], ["zonas", "zones"], ["automações", "automations"], ["scripts", "scripts"], ["Automações", "Automations"], ["Scripts", "Scripts"], ["Passiva", "Passive"], ["Ativa", "Active"], ["Atenção", "Attention"], ["Conformes", "Compliant"], ["Não conformes", "Non-compliant"], ["Desatualizados", "Outdated"], ["Todos os resultados", "All results"], ["Salvar políticas", "Save policies"], ["Políticas salvas.", "Policies saved."], ["Edit in Home Assistant", "Edit in Home Assistant"],
      ["Analisando recursos…", "Analyzing resources…"], ["Preparando sua auditoria…", "Preparing your audit…"],
      ["VISÃO GERAL", "OVERVIEW"], ["Olá, administrador", "Hello, administrator"], ["Uma visão rápida da organização da sua instalação.", "A quick view of your installation's organization."],
      ["Tudo revisado no estado atual.", "Everything reviewed in the current state."], ["Continue de onde você parou.", "Continue where you left off."],
      ["PROGRESSO DA REVISÃO", "REVIEW PROGRESS"], ["itens auditáveis", "auditable items"], ["conformes", "compliant"], ["pedem atenção", "need attention"], ["desatualizados", "outdated"],
      ["Resumo da auditoria", "Audit summary"], ["Conformidade e revisão são acompanhadas separadamente.", "Compliance and review progress are tracked separately."], ["Conformidade", "Compliance"], ["Atenção", "Attention"], ["Não conformes", "Non-compliant"], ["Andamento", "Progress"], ["Revisados", "Reviewed"], ["Pendentes", "Pending"], ["Ignorados", "Ignored"],
      ["INVENTÁRIO E AUDITORIA", "INVENTORY & AUDIT"], ["categorias", "categories"], ["precisam de atenção", "need attention"], ["Ver como tabela", "View as table"], ["categorias normalizadas", "normalized categories"], ["em automações", "in automations"], ["em scripts", "in scripts"], ["Buscar por nome ou escopo…", "Search by name or scope…"], ["Todos os resultados", "All results"], ["Conformes", "Compliant"], ["Não conformes", "Non-compliant"], ["Desatualizados", "Outdated"], ["Nenhuma categoria encontrada", "No categories found"], ["As categorias cadastradas nos escopos selecionados aparecerão aqui.", "Categories registered in the selected scopes will appear here."],
      ["INVENTÁRIO GEOGRÁFICO", "GEOGRAPHIC INVENTORY"], ["zonas configuradas", "configured zones"], ["Atualizar", "Refresh"], ["zonas inventariadas", "inventoried zones"], ["zonas passivas", "passive zones"], ["Buscar por nome ou identificador…", "Search by name or identifier…"], ["Nenhuma zona encontrada", "No zones found"], ["As zonas configuradas no Home Assistant aparecerão aqui.", "Zones configured in Home Assistant will appear here."], ["Nenhuma divergência geométrica encontrada.", "No geometric differences found."], ["Coordenadas indisponíveis", "Coordinates unavailable"], ["RAIO", "RADIUS"], ["COORDENADAS", "COORDINATES"], ["ESTADO", "STATE"], ["Passiva", "Passive"], ["Ativa", "Active"], ["LABELS", "LABELS"], ["Edit in Home Assistant", "Edit in Home Assistant"], ["Manage labels in Home Assistant", "Manage labels in Home Assistant"],
      ["Comparar automações e scripts", "Compare automations and scripts"], ["Ignorar diferenças de caixa", "Ignore case differences"], ["Comparar “Sala” e “sala” como iguais.", "Compare “Room” and “room” as equal."], ["Ignorar acentos", "Ignore accents"], ["Comparar nomes com e sem acentos como iguais.", "Compare names with and without accents as equal."], ["Normalizar separadores", "Normalize separators"], ["Tratar espaços, hífens e underscores como equivalentes.", "Treat spaces, hyphens, and underscores as equivalent."], ["Raio mínimo (m)", "Minimum radius (m)"], ["Raio máximo (m)", "Maximum radius (m)"], ["Ícone obrigatório", "Icon required"], ["Destacar zonas que não possuem ícone.", "Flag zones without an icon."], ["Detectar geometrias duplicadas", "Detect duplicate geometries"], ["Mesmo centro e mesmo raio.", "Same center and radius."], ["Normalização de Categories", "Categories normalization"], ["Aplicada apenas às categorias.", "Applied to categories only."], ["Regras para raios, ícones e duplicidades.", "Rules for radii, icons, and duplicates."], ["Regras de comparação de nomes e associações.", "Rules for comparing names and associations."], ["Cole a política visual configurada no Home Assistant.", "Paste the visual policy configured in Home Assistant."], ["Regras para comparar nomes e aliases expostos.", "Rules for comparing exposed names and aliases."],
      ["POLÍTICAS DO ORGANIZER", "ORGANIZER POLICIES"], ["Defina como a instalação deve ser auditada. Nada aqui altera recursos nativos.", "Define how the installation should be audited. Nothing here changes native resources."], ["Regras para nomes, ícones e consistência entre automações e scripts.", "Rules for names, icons, and consistency between automations and scripts."], ["Comparar entre escopos", "Compare across scopes"], ["Automações", "Automations"], ["Scripts", "Scripts"], ["Não", "No"], ["Sim", "Yes"], ["Tamanho mínimo", "Minimum length"], ["Idioma esperado", "Expected language"], ["Qualquer idioma", "Any language"], ["Português (Brasil)", "Portuguese (Brazil)"], ["Inglês", "English"], ["Espanhol", "Spanish"], ["Maiúsculas/minúsculas", "Case"], ["Qualquer combinação", "Any combination"], ["Somente minúsculas", "Lowercase only"], ["Somente maiúsculas", "Uppercase only"], ["Permitir espaços", "Allow spaces"], ["Permitir pontuação", "Allow punctuation"], ["Política copiada do Home Assistant", "Policy copied from Home Assistant"], ["Cole aqui a ordem dos tokens usada pelo HA. O Organizer apenas audita; nunca renomeia.", "Paste the token order used by HA here. Organizer audits only; it never renames anything."], ["Políticas salvas.", "Policies saved."], ["Salvar políticas", "Save policies"],
      ["Criada neste escopo", "Created in this scope"], ["Não encontrada neste escopo", "Not found in this scope"], ["Ver ", "View "], [" recurso", " resource"], ["Recursos", "Resources"], ["Recurso", "Resource"], ["Chave normalizada:", "Normalized key:"], ["Os escopos selecionados estão consistentes.", "The selected scopes are consistent."], ["Reabrir revisão", "Reopen review"], ["Marcar como revisada", "Mark as reviewed"], ["Ignorar", "Ignore"], ["MÓDULO", "MODULE"], ["itens encontrados", "items found"], ["Buscar neste módulo…", "Search this module…"], ["Ative este módulo nas configurações para iniciar uma auditoria.", "Enable this module in Settings to start an audit."], ["Nenhum item neste módulo", "No items in this module"], ["Nenhuma divergência encontrada", "No differences found"], ["Nenhum escopo", "No scope"], ["Reabrir", "Reopen"], ["Revisar", "Review"], ["Política auditada", "Audited policy"], ["O Home Assistant não expõe um padrão global. Esta análise usa a política do Organizer:", "Home Assistant does not expose a global pattern. This analysis uses the Organizer policy:"], ["O Home Assistant não expõe uma política global de nomenclatura. O Organizer mostra os IDs atuais e os compara com o padrão definido aqui, sem renomear nada.", "Home Assistant does not expose a global naming policy. Organizer shows the current IDs and compares them with the pattern defined here without renaming anything."], ["não configurada", "not configured"], ["Conforme", "Compliant"], ["Não conforme", "Non-compliant"], ["Pendente", "Pending"], ["Revisado", "Reviewed"], ["Ignorado", "Ignored"], ["Desatualizado", "Outdated"], ["Erro desconhecido", "Unknown error"], ["Normalização compartilhada", "Shared normalization"], ["Usada para comparar nomes em Categories, Areas, Zones e exposições.", "Used to compare names in Categories, Areas, Zones, and exposed entities."], ["Útil para detectar variações como “home-office” e “home_office”.", "Useful for detecting variations such as “home-office” and “home_office”."], ["Normalizar espaços, hífens e underscores", "Normalize spaces, hyphens, and underscores"], ["exposições", "exposed entities"], ["zonas inventariadas", "inventoried zones"], ["zonas passivas", "passive zones"], ["com atenção", "with attention"], ["Ver como cartões", "View as cards"], ["RESULTADO", "RESULT"], ["REVISÃO", "REVIEW"], ["ITEM", "ITEM"], ["ícone", "icon"]
    ];
    const replace = (value) => translations.reduce((text, [from, to]) => text.replaceAll(from, to), value)
      .replaceAll("Regras para nomes, icons e consistência entre automations e scripts.", "Rules for names, icons, and consistency between automations and scripts.")
      .replaceAll("Normalização de Categories", "Categories normalization")
      .replaceAll("Aplicada apenas às categorias.", "Applied to categories only.")
      .replaceAll("Regras para raios, ícones e duplicidades.", "Rules for radii, icons, and duplicates.")
      .replaceAll("Regras de comparação de nomes e associações.", "Rules for comparing names and associations.")
      .replaceAll("Cole a política visual configurada no Home Assistant.", "Paste the visual policy configured in Home Assistant.")
      .replaceAll("Regras para comparar nomes e aliases expostos.", "Rules for comparing exposed names and aliases.")
      .replaceAll("Ausente em: ", "Missing in: ")
      .replaceAll("Nome menor que ", "Name is shorter than ")
      .replaceAll(" caracteres", " characters")
      .replaceAll("Dispositivo sem área: ", "Device without area: ")
      .replaceAll("Zona com centro e raio idênticos", "Zone has identical center and radius")
      .replaceAll("Zona sem nome", "Zone has no name")
      .replaceAll("Zona sem ícone", "Zone has no icon")
      .replaceAll("Raio menor que ", "Radius is smaller than ")
      .replaceAll("Raio maior que ", "Radius is larger than ")
      .replaceAll("Entity ID fora do formato esperado ou com sufixo automático", "Entity ID has an unexpected format or an automatic suffix")
      .replaceAll("Entity ID não segue o padrão configurado", "Entity ID does not follow the configured pattern")
      .replaceAll("Nome de área duplicado após normalização", "Area name is duplicated after normalization")
      .replaceAll("Dispositivo sem área", "Device without area")
      .replaceAll("Nomes diferentes após normalização", "Names differ after normalization")
      .replaceAll("Ícones diferentes entre automações e scripts", "Icons differ between automations and scripts")
      .replaceAll("Categoria sem ícone", "Category has no icon")
      .replaceAll("Nome deve usar apenas minúsculas", "Name must use lowercase only")
      .replaceAll("Nome deve usar apenas maiúsculas", "Name must use uppercase only")
      .replaceAll("Espaços não são permitidos no nome", "Spaces are not allowed in the name")
      .replaceAll("Pontuação não é permitida no nome", "Punctuation is not allowed in the name")
      .replaceAll("Nome não parece usar o alfabeto esperado para ", "Name does not appear to use the expected alphabet for ");
    const walker = document.createTreeWalker(this, NodeFilter.SHOW_TEXT);
    const nodes = [];
    while (walker.nextNode()) nodes.push(walker.currentNode);
    nodes.forEach((node) => { node.nodeValue = replace(node.nodeValue); });
    this.querySelectorAll("[placeholder]").forEach((node) => { node.placeholder = replace(node.placeholder); });
    this.querySelectorAll("a[href]").forEach((link) => { link.target = "_blank"; link.rel = "noopener noreferrer"; });
  }

  async show(module) {
    this._module = module;
    this.setActive(module);
    const content = this.querySelector("#content");
    content.innerHTML = `<div class="loading"><span class="spinner"></span> Analyzing resources…</div>`;
    try {
      const data = module === "overview" ? await this.call("ha_organizer/overview") : module === "settings" ? await this.call("ha_organizer/config/get") : (await this.call("ha_organizer/scan")).modules[module] || [];
      if (module === "overview") this.overview(data);
      else if (module === "settings") this.settings(data);
      else if (module === "categories") this.categories(data);
      else if (module === "areas") this.areas(data);
      else if (module === "zones") this.zones(data);
      else if (module === "exposed") this.exposed(data);
      else this.table(module, data);
      this.localize();
    } catch (error) { this.showError(error); }
  }

  showError(error) {
    this.querySelector("#content").innerHTML = `<div class="empty error-state"><div class="empty-icon">!</div><h2>Unable to load this module</h2><p>Check that the integration is loaded and refresh the analysis.</p><code>${escapeHtml(error?.message || "Unknown error")}</code></div>`;
    this.localize();
  }

  overview(data) {
    const reviewed = Math.round((data.review_progress || 0) * 100);
    const stale = data.review?.stale || 0;
    const moduleProgress = Object.entries(data.module_progress || {});
    const moduleLabels = Object.fromEntries(MODULES.map(([id, label]) => [id, label]));
    this.querySelector("#content").innerHTML = `<div class="page-heading"><div><div class="eyebrow">OVERVIEW</div><h1>Hello, administrator <span><ha-icon icon="mdi:account-voice"></ha-icon></span></h1><p>A quick view of your installation's organization.</p></div><div class="health"><span class="health-dot"></span> Local audit</div></div>
      <section class="hero"><div><div class="eyebrow light">REVIEW PROGRESS</div><div class="hero-number">${reviewed}<small>%</small></div><p>${reviewed === 100 ? "Everything reviewed in the current state." : "Continue where you left off."}</p></div><div class="progress-ring" style="--progress:${reviewed * 3.6}deg"><div>${reviewed}%</div></div></section>
      <section class="organizer-flow"><div class="section-title"><div><h2>Recommended organization flow</h2><p>Follow this order to make the installation easier to maintain.</p></div></div><div class="flow-steps">${["Areas", "Zones", "Labels", "Categories", "Entity IDs", "Exposed & Aliases"].map((label, index) => { const module = MODULES.find((entry) => entry[1] === label); return `<button class="flow-step" data-module="${module?.[0] || "overview"}"><b>${index + 1}</b><span><ha-icon icon="${module?.[2] || "mdi:circle-outline"}"></ha-icon></span><small>${label}</small></button>${index < 5 ? "<i>→</i>" : ""}`; }).join("")}</div></section>
      <div class="metric-grid"><article class="metric-card"><div class="metric-icon purple">◈</div><div><strong>${data.total || 0}</strong><span>auditable items</span></div></article><article class="metric-card"><div class="metric-icon green">✓</div><div><strong>${data.compliance?.compliant || 0}</strong><span>compliant</span></div></article><article class="metric-card"><div class="metric-icon orange">!</div><div><strong>${(data.compliance?.attention || 0) + (data.compliance?.non_compliant || 0)}</strong><span>need attention</span></div></article><article class="metric-card"><div class="metric-icon red">↻</div><div><strong>${stale}</strong><span>outdated</span></div></article></div>
      <div class="section-title"><div><h2>Audit summary</h2><p>Compliance and review progress are tracked separately.</p></div></div><div class="summary-grid"><div class="summary-card"><h3>Compliance</h3>${bar("Compliant", data.compliance?.compliant || 0, data.total, "green")}${bar("Attention", data.compliance?.attention || 0, data.total, "orange")}${bar("Non-compliant", data.compliance?.non_compliant || 0, data.total, "red")}</div><div class="summary-card"><h3>Progress</h3>${bar("Reviewed", data.review?.reviewed || 0, data.total, "purple")}${bar("Pending", data.review?.pending || 0, data.total, "gray")}${bar("Ignored", data.review?.ignored || 0, data.total, "orange")}</div></div><div class="section-title module-progress-title"><div><h2>Progress by module</h2><p>Review progress for each audited area.</p></div></div><div class="module-progress-grid">${moduleProgress.map(([id, progress]) => bar(moduleLabels[id] || id, progress.reviewed, progress.total, "purple")).join("")}</div>`;
    this.querySelectorAll(".flow-step").forEach((button) => { button.onclick = () => this.show(button.dataset.module); });
  }

  exposed(rows) {
    const aliasesFor = (item) => [...new Set((item.entries || []).filter((entry) => entry.name !== item.title).map((entry) => entry.name))];
    const exposedEntityCount = new Set(rows.flatMap((item) => item.entities || [])).size;
    const aliasCount = rows.reduce((count, item) => count + aliasesFor(item).length, 0);
    const attention = rows.filter((item) => item.compliance_status !== "compliant").length;
    const row = (item) => {
      const aliases = aliasesFor(item);
      const assistants = [...new Set((item.entries || []).flatMap((entry) => entry.assistants || []))];
      const finding = (item.findings || []).map((entry) => entry.message).join(" · ") || "No differences found";
      const reopen = item.review_status === "reviewed";
      const ignore = item.review_status === "ignored" ? "" : `<button class="ignore" data-key="${escapeHtml(item.item_key)}" data-fp="${escapeHtml(item.fingerprint)}">Ignore</button>`;
      return `<article class="exposed-list-row" data-search="${escapeHtml(`${item.title} ${aliases.join(" ")} ${assistants.join(" ")} ${finding}`.toLowerCase())}" data-status="${escapeHtml(item.compliance_status)}" data-review="${escapeHtml(item.review_status)}"><div class="exposed-entity"><span class="exposed-icon"><ha-icon icon="mdi:account-voice"></ha-icon></span><div><strong>${escapeHtml(item.title)}</strong><small>${escapeHtml(item.id)}</small></div></div><div class="exposed-aliases"><b>ALIASES</b>${aliases.length ? `<div>${aliases.map((alias) => `<span class="alias-chip">${escapeHtml(alias)}</span>`).join("")}</div>` : "<small>No aliases</small>"}</div><div class="exposed-assistants"><b>ASSISTANTS</b><span>${assistants.length ? assistants.map(escapeHtml).join(", ") : "—"}</span></div><div class="exposed-row-status">${statusPill(item.compliance_status)}${statusPill(item.review_status)}</div><div class="exposed-row-actions"><button class="review ${reopen ? "reopen-action" : "review-action"}" data-key="${escapeHtml(item.item_key)}" data-fp="${escapeHtml(item.fingerprint)}">${reopen ? "Reopen" : "Review"}</button>${ignore}</div><p class="exposed-finding">${escapeHtml(finding)}</p></article>`;
    };
    this.querySelector("#content").innerHTML = `<div class="page-heading compact"><div><div class="eyebrow">MODULE</div><h1>Exposed & Aliases</h1><p>${exposedEntityCount} exposed entities · ${aliasCount} aliases found</p></div><div class="page-actions"><a class="view-switch" href="/config/voice-assistants/expose">Edit in Home Assistant ↗</a></div></div><div class="exposed-summary"><div><strong>${exposedEntityCount}</strong><small>exposed entities</small></div><div><strong>${aliasCount}</strong><small>aliases found</small></div><div><strong>${attention}</strong><small>need attention</small></div></div><div class="table-toolbar"><div class="search"><span>⌕</span><input id="exposed-search" placeholder="Search exposed entities and aliases…"></div><select id="exposed-status-filter"><option value="all">All results</option><option value="compliant">Compliant</option><option value="attention">Attention</option><option value="non_compliant">Non-compliant</option><option value="stale">Outdated</option></select></div><section class="exposed-list">${rows.length ? rows.map(row).join("") : `<div class="empty"><div class="empty-icon"><ha-icon icon="mdi:account-voice"></ha-icon></div><h3>No exposed entities found</h3><p>Entities exposed to voice assistants will appear here.</p></div>`}</section>`;
    const filter = () => { const query = this.querySelector("#exposed-search").value.toLowerCase(); const status = this.querySelector("#exposed-status-filter").value; this.querySelectorAll(".exposed-list-row").forEach((item) => { item.hidden = !item.dataset.search.includes(query) || (status !== "all" && item.dataset.status !== status && !(status === "stale" && item.dataset.review !== "stale")); }); };
    this.querySelector("#exposed-search").oninput = filter;
    this.querySelector("#exposed-status-filter").onchange = filter;
    this.querySelectorAll(".review,.ignore").forEach((button) => button.onclick = async () => { const status = button.classList.contains("ignore") ? "ignored" : (button.classList.contains("reopen-action") ? "pending" : "reviewed"); await this.call("ha_organizer/review/set", { item_key: button.dataset.key, status, fingerprint: button.dataset.fp }); await this.show("exposed"); });
  }

  exposedCard(item) {
    const aliases = [...new Set((item.entries || []).filter((entry) => entry.name !== item.title).map((entry) => entry.name))];
    const assistants = [...new Set((item.entries || []).flatMap((entry) => entry.assistants || []))];
    const finding = (item.findings || []).map((entry) => entry.message).join(" · ") || "No differences found";
    const reopen = item.review_status === "reviewed";
    const ignore = item.review_status === "ignored" ? "" : `<button class="ignore" data-key="${escapeHtml(item.item_key)}" data-fp="${escapeHtml(item.fingerprint)}">Ignore</button>`;
    return `<article class="exposed-card"><div class="exposed-card-head"><div class="exposed-icon"><ha-icon icon="mdi:account-voice"></ha-icon></div><div><h3>${escapeHtml(item.title)}</h3><code>${escapeHtml(item.id)}</code></div><div class="exposed-status">${statusPill(item.compliance_status)} ${statusPill(item.review_status)}</div></div><div class="exposed-details"><div><small>ALIASES</small>${aliases.length ? `<p>${aliases.map((alias) => `<span class="alias-chip">${escapeHtml(alias)}</span>`).join("")}</p>` : "<p class=\"muted\">No aliases</p>"}</div><div><small>ASSISTANTS</small><p>${assistants.length ? assistants.map(escapeHtml).join(", ") : "—"}</p></div></div><div class="exposed-finding">${escapeHtml(finding)}</div><div class="exposed-actions"><button class="review ${reopen ? "reopen-action" : "review-action"}" data-key="${escapeHtml(item.item_key)}" data-fp="${escapeHtml(item.fingerprint)}">${reopen ? "Reopen" : "Review"}</button>${ignore}</div></article>`;
  }

  categories(rows) {
    const summaryAutomationCount = rows.filter((item) => item.scopes?.automation).length;
    const summaryScriptCount = rows.filter((item) => item.scopes?.script).length;
    this.table("categories", rows);
    this.querySelector("#category-card-view")?.remove();
    this.querySelector(".page-heading")?.insertAdjacentHTML("afterend", `<div class="category-summary"><div><span class="summary-symbol">⌁</span><div><strong>${rows.length}</strong><small>normalized categories</small></div></div><div><span class="summary-symbol automation">⚙</span><div><strong>${summaryAutomationCount}</strong><small>in automations</small></div></div><div><span class="summary-symbol script">↝</span><div><strong>${summaryScriptCount}</strong><small>in scripts</small></div></div></div>`);
    this.localize();
    return;
    /* istanbul ignore next */
    const attention = rows.filter((item) => item.compliance_status !== "compliant").length;
    const automationCount = rows.filter((item) => item.scopes?.automation).length;
    const scriptCount = rows.filter((item) => item.scopes?.script).length;
    this.querySelector("#content").innerHTML = `<div class="page-heading compact"><div><div class="eyebrow">INVENTÁRIO E AUDITORIA</div><h1>Categories</h1><p>${rows.length} categorias · ${attention} precisam de atenção</p></div><button class="view-switch" id="category-table-view">▤ Ver como tabela</button></div><div class="category-summary"><div><span class="summary-symbol">⌁</span><div><strong>${rows.length}</strong><small>categorias normalizadas</small></div></div><div><span class="summary-symbol automation">⚙</span><div><strong>${automationCount}</strong><small>em automações</small></div></div><div><span class="summary-symbol script">↝</span><div><strong>${scriptCount}</strong><small>em scripts</small></div></div></div><div class="category-toolbar"><div class="search"><span>⌕</span><input id="category-search" placeholder="Buscar por nome ou escopo…"></div><select id="category-status"><option value="all">Todos os resultados</option><option value="compliant">Conformes</option><option value="attention">Atenção</option><option value="non_compliant">Não conformes</option><option value="stale">Desatualizados</option></select></div><div class="category-grid">${rows.length ? rows.map((item) => this.categoryCard(item)).join("") : `<div class="empty"><div class="empty-icon">✓</div><h3>Nenhuma categoria encontrada</h3><p>As categorias cadastradas nos escopos selecionados aparecerão aqui.</p></div>`}</div>`;
    const filter = () => { const query = this.querySelector("#category-search").value.toLowerCase(); const status = this.querySelector("#category-status").value; this.querySelectorAll(".category-card").forEach((card) => { card.hidden = !card.dataset.search.includes(query) || (status !== "all" && card.dataset.status !== status && !(status === "stale" && card.dataset.review !== "stale")); }); };
    this.querySelector("#category-search").oninput = filter;
    this.querySelector("#category-status").onchange = filter;
    this.querySelector("#category-table-view").onclick = () => this.table("categories", rows);
    this.querySelectorAll(".category-review,.category-ignore").forEach((button) => button.onclick = async () => { await this.call("ha_organizer/review/set", { item_key: button.dataset.key, status: button.classList.contains("category-review") ? (button.classList.contains("reopen-action") ? "pending" : "reviewed") : "ignored", fingerprint: button.dataset.fp }); await this.show("categories"); });
    this.querySelectorAll(".category-resources").forEach((button) => button.onclick = () => button.parentElement.classList.toggle("expanded"));
  }

  zones(rows) {
    const attention = rows.filter((item) => item.compliance_status !== "compliant").length;
    const row = (item) => { const finding = (item.findings || []).map((entry) => entry.message).join(" · ") || "No overlapping zones found."; const coordinates = item.latitude == null || item.longitude == null ? "Unavailable" : `${Number(item.latitude).toFixed(4)}, ${Number(item.longitude).toFixed(4)}`; const radius = item.radius == null ? "—" : `${Number(item.radius).toFixed(1).replace(/\.0$/, "")} m`; const reopen = item.review_status === "reviewed"; const ignore = item.review_status === "ignored" ? "" : `<button class="ignore" data-key="${escapeHtml(item.item_key)}" data-fp="${escapeHtml(item.fingerprint)}">Ignore</button>`; return `<tr data-search="${escapeHtml(`${item.title} ${item.id} ${finding}`.toLowerCase())}" data-status="${escapeHtml(item.compliance_status)}" data-review="${escapeHtml(item.review_status)}"><td><div class="zone-table-name"><span class="zone-table-icon">${item.icon ? `<ha-icon icon="${escapeHtml(item.icon)}"></ha-icon>` : "◎"}</span><span><strong>${escapeHtml(item.title)}</strong><small>${escapeHtml(item.id)}</small></span></div></td><td>${radius}</td><td><code>${escapeHtml(coordinates)}</code></td><td>${item.passive ? "Passive" : "Active"}</td><td><span class="zone-table-finding ${item.findings?.length ? "has-finding" : ""}">${escapeHtml(finding)}</span></td><td>${statusPill(item.compliance_status)}<br>${statusPill(item.review_status)}</td><td class="actions"><button class="review ${reopen ? "reopen-action" : "review-action"}" data-key="${escapeHtml(item.item_key)}" data-fp="${escapeHtml(item.fingerprint)}">${reopen ? "Reopen" : "Review"}</button>${ignore}</td></tr>`; };
    this.querySelector("#content").innerHTML = `<div class="page-heading compact"><div><div class="eyebrow">GEOGRAPHIC INVENTORY</div><h1>Zones</h1><p>${rows.length} configured zones · ${attention} need attention</p></div><div class="page-actions"><a class="view-switch" href="/config/zone">Edit in Home Assistant ↗</a><button class="refresh" id="zones-refresh">↻ Refresh</button></div></div><div class="zone-summary"><div><strong>${rows.length}</strong><small>inventoried zones</small></div><div><strong>${rows.filter((item) => item.passive).length}</strong><small>passive zones</small></div><div><strong>${attention}</strong><small>need attention</small></div></div><div class="category-toolbar"><div class="search"><span>⌕</span><input id="zone-search" placeholder="Search by name or identifier…"></div><select id="zone-status"><option value="all">All results</option><option value="compliant">Compliant</option><option value="attention">Attention</option><option value="non_compliant">Non-compliant</option><option value="stale">Outdated</option></select></div><div class="table-card zone-table"><table><thead><tr><th>ZONE</th><th>RADIUS</th><th>COORDINATES</th><th>STATE</th><th>AUDIT RESULT</th><th>STATUS</th><th></th></tr></thead><tbody>${rows.length ? rows.map(row).join("") : `<tr><td colspan="7"><div class="empty"><div class="empty-icon"><ha-icon icon="mdi:map-marker-outline"></ha-icon></div><h3>No zones found</h3><p>Zones configured in Home Assistant will appear here.</p></div></td></tr>`}</tbody></table></div>`;
    const filter = () => { const query = this.querySelector("#zone-search").value.toLowerCase(); const status = this.querySelector("#zone-status").value; this.querySelectorAll(".zone-table tbody tr[data-search]").forEach((card) => { card.hidden = !card.dataset.search.includes(query) || (status !== "all" && card.dataset.status !== status && !(status === "stale" && card.dataset.review !== "stale")); }); };
    this.querySelector("#zone-search").oninput = filter;
    this.querySelector("#zone-status").onchange = filter;
    this.querySelector("#zones-refresh").onclick = () => this.show("zones");
    this.querySelectorAll(".review,.ignore").forEach((button) => button.onclick = async () => { const status = button.classList.contains("ignore") ? "ignored" : (button.classList.contains("reopen-action") ? "pending" : "reviewed"); await this.call("ha_organizer/review/set", { item_key: button.dataset.key, status, fingerprint: button.dataset.fp }); await this.show("zones"); });
  }

  zoneCard(item) {
    const finding = (item.findings || []).map((entry) => entry.message).join(" · ") || "Nenhuma divergência geométrica encontrada.";
    const coordinates = item.latitude == null || item.longitude == null ? "Coordenadas indisponíveis" : `${Number(item.latitude).toFixed(4)}, ${Number(item.longitude).toFixed(4)}`;
    const reopen = item.review_status === "reviewed";
    const ignore = item.review_status === "ignored" ? "" : `<button class="zone-ignore ignore-action" data-key="${escapeHtml(item.item_key)}" data-fp="${escapeHtml(item.fingerprint)}">Ignore</button>`;
    return `<article class="zone-card" data-search="${escapeHtml(`${item.title} ${item.id} ${finding}`.toLowerCase())}" data-status="${escapeHtml(item.compliance_status)}" data-review="${escapeHtml(item.review_status)}"><div class="zone-card-head"><div class="zone-symbol">${item.icon ? `<ha-icon icon="${escapeHtml(item.icon)}"></ha-icon>` : "◎"}</div><div class="zone-name"><h3>${escapeHtml(item.title)}</h3><small>${escapeHtml(item.id)}</small></div><div>${statusPill(item.compliance_status)} ${statusPill(item.review_status)}</div></div><div class="zone-details"><div><span>RADIUS</span><b>${item.radius == null ? "—" : `${escapeHtml(item.radius)} m`}</b></div><div><span>COORDINATES</span><b>${escapeHtml(coordinates)}</b></div><div><span>STATE</span><b>${item.passive ? "Passive" : "Active"}</b></div></div><div class="zone-finding ${item.findings?.length ? "has-finding" : ""}"><span>${item.findings?.length ? "!" : "✓"}</span>${escapeHtml(finding)}</div><div class="zone-actions"><button class="zone-review ${reopen ? "reopen-action" : "review-action"}" data-key="${escapeHtml(item.item_key)}" data-fp="${escapeHtml(item.fingerprint)}">${reopen ? "Reopen" : "Review"}</button>${ignore}</div></article>`;
  }

  async settings(config) {
    await this.settingsForm(config);
  }

  async settingsForm(config) {
    const categories = { scopes: ["automation", "script", "scene"], require_icon: false, min_length: 0, language: "any", case_policy: "any", allow_spaces: true, allow_punctuation: true, ...(config.categories || {}) };
    const areas = config.modules?.areas?.settings || {};
    const zones = config.zones || {};
    const labels = config.labels || {};
    const modulePolicy = (name) => config.modules?.[name]?.settings || {};
    const checked = (value) => value ? "checked" : "";
    const selected = (value, expected) => value === expected ? "selected" : "";
    const normalizationFields = (name, values) => `<label class="check-setting"><input type="checkbox" name="${name}_case_insensitive" ${checked(values.case_insensitive !== false)}><span><b>Ignore case differences</b><small>Treat names that differ only by uppercase or lowercase characters as equal.</small></span></label><label class="check-setting"><input type="checkbox" name="${name}_ignore_accents" ${checked(values.ignore_accents !== false)}><span><b>Ignore accents</b><small>Treat accented and unaccented versions of a name as equal.</small></span></label><label class="check-setting"><input type="checkbox" name="${name}_normalize_separators" ${checked(values.normalize_separators !== false)}><span><b>Normalize separators</b><small>Treat spaces, hyphens, and underscores as equivalent.</small></span></label>`;
    this.querySelector("#content").innerHTML = `<div class="page-heading compact"><div><div class="eyebrow">ORGANIZER POLICIES</div><h1>Settings</h1><p>Choose how Organizer audits your installation. These settings never edit Home Assistant resources.</p></div></div><form class="settings-grid" id="settings-form"><section class="settings-card"><div class="settings-card-title"><span class="settings-icon"><ha-icon icon="mdi:shape-outline"></ha-icon></span><div><h2>Categories</h2><p>Rules for category names, icons, and selected scopes.</p></div></div><label class="check-setting"><input type="checkbox" name="category_require_equal" ${checked(categories.compare !== false)}><span><b>Require equal categories across scopes</b><small>Compare category names and icons in Automation, Script, and Scene.</small></span></label><label class="check-setting"><input type="checkbox" name="category_scene" ${checked(categories.scopes?.includes("scene"))}><span><b>Include scenes</b><small>Add Scene to the category scope comparison.</small></span></label><div class="setting-two"><label>Require icon<small>Flag categories that have no icon.</small><select name="category_require_icon"><option value="false" ${selected(categories.require_icon, false)}>No</option><option value="true" ${selected(categories.require_icon, true)}>Yes</option></select></label><label>Minimum name length<small>Flag names shorter than this number of characters; use 0 to disable.</small><input name="category_min_length" type="number" min="0" value="${categories.min_length}"></label></div><div class="setting-two"><label>Expected language<small>Flag category names that do not match this language.</small><select name="category_language"><option value="any" ${selected(categories.language, "any")}>Any language</option><option value="pt-BR" ${selected(categories.language, "pt-BR")}>Portuguese (Brazil)</option><option value="en" ${selected(categories.language, "en")}>English</option><option value="es" ${selected(categories.language, "es")}>Spanish</option></select></label><label>Name case<small>Set the capitalization required for category names.</small><select name="category_case_policy"><option value="any" ${selected(categories.case_policy, "any")}>Any combination</option><option value="lowercase" ${selected(categories.case_policy, "lowercase")}>Lowercase only</option><option value="uppercase" ${selected(categories.case_policy, "uppercase")}>Uppercase only</option></select></label></div><label class="check-setting"><input type="checkbox" name="category_allow_spaces" ${checked(categories.allow_spaces !== false)}><span><b>Allow spaces</b><small>Allow spaces in category names.</small></span></label><label class="check-setting"><input type="checkbox" name="category_allow_punctuation" ${checked(categories.allow_punctuation !== false)}><span><b>Allow punctuation</b><small>Allow punctuation characters in category names.</small></span></label>${normalizationFields("categories", categories.normalization || {})}</section><section class="settings-card"><div class="settings-card-title"><span class="settings-icon"><ha-icon icon="mdi:home-outline"></ha-icon></span><div><h2>Areas</h2><p>Rules for area metadata and name comparison.</p></div></div><label class="check-setting"><input type="checkbox" name="area_require_floor" ${checked(areas.require_floor)}><span><b>Require floor</b><small>Flag areas that are not assigned to a floor.</small></span></label><label class="check-setting"><input type="checkbox" name="area_require_aliases" ${checked(areas.require_aliases)}><span><b>Require aliases</b><small>Flag areas without alternative names.</small></span></label><label class="check-setting"><input type="checkbox" name="area_require_picture" ${checked(areas.require_picture)}><span><b>Require picture</b><small>Flag areas without a picture.</small></span></label><div class="setting-two"><label>Name case<small>Set the capitalization required for area names.</small><select name="area_case_policy"><option value="any" ${selected(areas.case_policy || "any", "any")}>Any combination</option><option value="capitalized" ${selected(areas.case_policy, "capitalized")}>Start with uppercase</option><option value="lowercase" ${selected(areas.case_policy, "lowercase")}>Lowercase only</option></select></label></div>${normalizationFields("areas", areas.normalization || areas)}</section><section class="settings-card"><div class="settings-card-title"><span class="settings-icon"><ha-icon icon="mdi:map-marker-outline"></ha-icon></span><div><h2>Zones</h2><p>Rules for zone geometry, icons, and name comparison.</p></div></div><div class="setting-two"><label>Minimum radius (m)<small>Flag zones below this radius; use 0 to disable.</small><input type="number" min="0" name="zone_min_radius" value="${zones.min_radius || 0}"></label><label>Maximum radius (m)<small>Flag zones above this radius; use 0 to disable.</small><input type="number" min="0" name="zone_max_radius" value="${zones.max_radius || 0}"></label></div><label class="check-setting"><input type="checkbox" name="zone_require_icon" ${checked(zones.require_icon)}><span><b>Require icon</b><small>Flag zones without an icon.</small></span></label><label class="check-setting"><input type="checkbox" name="zone_detect_duplicate" ${checked(zones.detect_duplicate_geometry !== false)}><span><b>Detect duplicate geometry</b><small>Flag zones with the same center and radius.</small></span></label><label class="check-setting"><input type="checkbox" name="zone_detect_overlap" ${checked(zones.detect_overlapping_geometry !== false)}><span><b>Detect overlapping zones</b><small>Flag zones whose circular boundaries overlap.</small></span></label>${normalizationFields("zones", zones.normalization || {})}</section><section class="settings-card"><div class="settings-card-title"><span class="settings-icon"><ha-icon icon="mdi:tag-outline"></ha-icon></span><div><h2>Labels</h2><p>Rules for label metadata and name comparison.</p></div></div><div class="setting-two"><label>Minimum name length<small>Flag label names shorter than this value.</small><input type="number" min="1" name="label_min_name" value="${labels.min_name_length || 1}"></label><label>Minimum description length<small>Flag descriptions shorter than this value; use 0 to disable.</small><input type="number" min="0" name="label_min_description" value="${labels.min_description_length || 0}"></label></div><label class="check-setting"><input type="checkbox" name="label_require_icon" ${checked(labels.require_icon)}><span><b>Require icon</b><small>Flag labels without an icon.</small></span></label><label class="check-setting"><input type="checkbox" name="label_require_color" ${checked(labels.require_color)}><span><b>Require color</b><small>Flag labels without a color.</small></span></label></section><section class="settings-card"><div class="settings-card-title"><span class="settings-icon"><ha-icon icon="mdi:identifier"></ha-icon></span><div><h2>Entity IDs</h2><p>The naming policy used only for Organizer audits.</p></div></div><label class="setting-label">Home Assistant naming policy<small>Compare entity IDs with this pattern; Organizer does not rename entities.</small></label><textarea class="policy-input" name="entity_policy" rows="3" placeholder="{domain}.{area}_{device}_{entity}">${escapeHtml(config.entity_id_pattern || "{domain}.{area}_{device}_{entity}")}</textarea>${normalizationFields("entity_ids", modulePolicy("entity_ids").normalization || modulePolicy("entity_ids"))}</section><section class="settings-card"><div class="settings-card-title"><span class="settings-icon"><ha-icon icon="mdi:account-voice"></ha-icon></span><div><h2>Exposed & Aliases</h2><p>Rules for comparing names used by voice assistants.</p></div></div>${normalizationFields("exposed", modulePolicy("exposed").normalization || modulePolicy("exposed"))}</section><div class="settings-actions"><button type="button" class="danger-action" id="reset-reviews">Reset review history</button><button type="button" class="secondary-action" id="reset-config">Restore defaults</button><span id="settings-message"></span><button type="submit" class="save-settings">Save policies</button></div></form>`;
    const form = this.querySelector("#settings-form");
    const settingsActions = form.querySelector(".settings-actions");
    const cardsByTitle = Object.fromEntries([...form.querySelectorAll(".settings-card")]
      .map((card) => [card.querySelector("h2")?.textContent, card]));
    ["Areas", "Zones", "Labels", "Categories", "Entity IDs", "Exposed & Aliases"]
      .forEach((title) => settingsActions.before(cardsByTitle[title]));
    form.onsubmit = async (event) => { event.preventDefault(); const data = new FormData(form); const isChecked = (name) => Boolean(data.get(name)); const minRadius = Number(data.get("zone_min_radius") || 0); const maxRadius = Number(data.get("zone_max_radius") || 0); if (minRadius < 0 || maxRadius < 0 || (maxRadius > 0 && maxRadius < minRadius)) { window.alert("Zone radius limits are invalid. Maximum radius must be zero or greater than the minimum."); return; } const normalization = (name) => ({ case_insensitive: isChecked(`${name}_case_insensitive`), ignore_accents: isChecked(`${name}_ignore_accents`), normalize_separators: isChecked(`${name}_normalize_separators`) }); const next = { ...config, categories: { ...categories, compare: isChecked("category_require_equal"), scopes: ["automation", "script", ...(isChecked("category_scene") ? ["scene"] : [])], require_icon: data.get("category_require_icon") === "true", min_length: Number(data.get("category_min_length") || 0), language: data.get("category_language"), case_policy: data.get("category_case_policy"), allow_spaces: isChecked("category_allow_spaces"), allow_punctuation: isChecked("category_allow_punctuation"), normalization: normalization("categories") }, zones: { ...zones, detect_duplicate_geometry: isChecked("zone_detect_duplicate"), detect_overlapping_geometry: isChecked("zone_detect_overlap"), min_radius: minRadius, max_radius: maxRadius, require_icon: isChecked("zone_require_icon"), normalization: normalization("zones") }, labels: { ...labels, min_name_length: Number(data.get("label_min_name") || 1), min_description_length: Number(data.get("label_min_description") || 0), require_icon: isChecked("label_require_icon"), require_color: isChecked("label_require_color") }, entity_id_pattern: data.get("entity_policy") || config.entity_id_pattern, modules: { ...config.modules, areas: { ...(config.modules?.areas || {}), settings: { ...areas, require_floor: isChecked("area_require_floor"), require_aliases: isChecked("area_require_aliases"), require_picture: isChecked("area_require_picture"), case_policy: data.get("area_case_policy"), normalization: normalization("areas") } }, entity_ids: { ...(config.modules?.entity_ids || {}), settings: { ...modulePolicy("entity_ids"), normalization: normalization("entity_ids") } }, exposed: { ...(config.modules?.exposed || {}), settings: { ...modulePolicy("exposed"), normalization: normalization("exposed") } } } }; await this.call("ha_organizer/config/update", { config: next }); this.querySelector("#settings-message").textContent = "Policies saved."; };
    this.querySelector("#reset-reviews").onclick = async () => { if (!window.confirm("Reset all reviewed and ignored items?")) return; await this.call("ha_organizer/reviews/reset"); await this.show("settings"); };
    this.querySelector("#reset-config").onclick = async () => { if (!window.confirm("Restore all Organizer settings to their defaults?")) return; await this.call("ha_organizer/config/reset"); await this.show("settings"); };
  }

  categoryCard(item) {
    const scope = (name, label) => { const resources = item.resources?.[name] || []; const present = Boolean(item.scopes?.[name]); return `<div class="category-scope ${present ? "present" : "missing"}"><div class="scope-heading"><span class="scope-icon">${name === "automation" ? "⚙" : "↝"}</span><b>${label}</b><span class="scope-count">${resources.length}</span></div><div class="scope-state">${present ? "Criada neste escopo" : "Não encontrada neste escopo"}</div>${present && resources.length ? `<button class="category-resources">Ver ${resources.length} recurso${resources.length === 1 ? "" : "s"}</button><div class="resource-list">${resources.map((resource) => `<span>${escapeHtml(resource.entity_id || resource.name || "Recurso")}</span>`).join("")}</div>` : ""}</div>`; };
    const finding = (item.findings || []).map((entry) => entry.message).join(" · ") || "Os escopos selecionados estão consistentes.";
    const icon = item.icon ? `<ha-icon icon="${escapeHtml(item.icon)}"></ha-icon>` : "<span class=\"category-default-icon\">⌁</span>";
    const reopen = item.review_status === "reviewed";
    const ignore = item.review_status === "ignored" ? "" : `<button class="category-ignore ignore-action" data-key="${escapeHtml(item.item_key)}" data-fp="${escapeHtml(item.fingerprint)}">Ignore</button>`;
    return `<article class="category-card" data-search="${escapeHtml(`${item.title} ${(item.scopes && Object.keys(item.scopes).join(" ")) || ""} ${finding}`.toLowerCase())}" data-status="${escapeHtml(item.compliance_status)}" data-review="${escapeHtml(item.review_status)}"><div class="category-card-head"><div class="category-name"><span class="category-icon">${icon}</span><div><h3>${escapeHtml(item.title)}</h3><small>Chave normalizada: <code>${escapeHtml(item.id)}</code></small></div></div><div>${statusPill(item.compliance_status)} ${statusPill(item.review_status)}</div></div><div class="category-scopes">${scope("automation", "Automações")}${scope("script", "Scripts")}</div><div class="category-finding ${item.findings?.length ? "has-finding" : ""}"><span>${item.findings?.length ? "!" : "✓"}</span>${escapeHtml(finding)}</div><div class="category-card-actions"><button class="category-review ${reopen ? "reopen-action" : "review-action"}" data-key="${escapeHtml(item.item_key)}" data-fp="${escapeHtml(item.fingerprint)}">${reopen ? "Reopen" : "Review"}</button>${ignore}</div></article>`;
  }

  areas(rows) {
    const areaRows = rows.filter((item) => item.area_kind !== "unassigned_device" && !String(item.id).startsWith("device:"));
    const unassignedRows = rows.filter((item) => item.area_kind === "unassigned_device" || String(item.id).startsWith("device:"));
    const attention = rows.filter((item) => item.compliance_status !== "compliant").length;
    const areaRow = (item) => {
      const devices = item.device_details || [];
      const finding = (item.findings || []).map((entry) => entry.message).join(" · ") || "No differences found";
      const picture = item.picture
        ? `<img class="areas-picture" src="${escapeHtml(item.picture)}" alt="Picture of ${escapeHtml(item.title)}">`
        : `<span class="areas-picture areas-picture-empty"><ha-icon icon="mdi:home-outline"></ha-icon></span>`;
      const deviceList = devices.length
        ? devices.map((device) => `<a class="areas-device-link" href="/config/devices/device/${encodeURIComponent(device.id)}"><span>${escapeHtml(device.name || device.id)}</span><small>Open device ↗</small></a>`).join("")
        : `<div class="areas-no-devices">No devices assigned to this area.</div>`;
      const areaIcon = item.icon ? `<ha-icon icon="${escapeHtml(item.icon)}"></ha-icon>` : `<ha-icon icon="mdi:home-outline"></ha-icon>`;
      return `<article class="areas-row" data-search="${escapeHtml(`${item.title} ${devices.map((device) => device.name || device.id).join(" ")} ${finding}`.toLowerCase())}"><button class="areas-expand" aria-expanded="false"><span class="areas-chevron">›</span>${picture}<span class="areas-primary"><strong>${escapeHtml(item.title)}</strong><small>${item.floor ? `Floor: ${escapeHtml(item.floor)}` : "No floor"} · ${devices.length} devices · ${(item.entities || []).length} entities</small><small>${escapeHtml(finding)}</small></span><span class="areas-status">${statusPill(item.compliance_status)} ${statusPill(item.review_status)}</span></button><div class="areas-devices" hidden><div class="areas-expanded-heading"><span class="areas-icon">${areaIcon}</span><a href="/config/areas/area/${encodeURIComponent(item.id)}">Open area in Home Assistant ↗</a></div><div class="areas-devices-title">Devices in this area</div>${deviceList}</div></article>`;
    };
    const orphanRow = (item) => {
      const device = item.device_details?.[0] || item.devices?.[0] || {};
      return `<a class="unassigned-device" data-search="${escapeHtml(`${item.title} ${device.name || ""}`.toLowerCase())}" href="/config/devices/device/${encodeURIComponent(device.id || String(item.id).replace(/^device:/, ""))}"><span class="item-dot attention"></span><span><strong>${escapeHtml(device.name || item.title.replace(/^Dispositivo sem área: /, ""))}</strong><small>Device without area</small></span><span>Open device ↗</span></a>`;
    };
    this.querySelector("#content").innerHTML = `<div class="page-heading compact"><div><div class="eyebrow">MODULE</div><h1>Areas</h1><p>${areaRows.length} areas · ${unassignedRows.length} devices without area · ${attention} need attention</p></div><div class="page-actions"><a class="view-switch" href="/config/areas/dashboard">Edit in Home Assistant ↗</a></div></div><div class="table-toolbar"><div class="search"><span>⌕</span><input id="search" placeholder="Search areas and devices…"></div></div><section class="areas-section"><div class="areas-section-heading"><div><h2>Areas</h2><p>Configured areas and their assigned devices.</p></div><span>${areaRows.length}</span></div><div class="areas-list">${areaRows.length ? areaRows.map(areaRow).join("") : `<div class="areas-empty">No areas found.</div>`}</div></section><section class="areas-section unassigned-section"><div class="areas-section-heading"><div><h2>Devices without area</h2><p>Devices that still need an area assignment.</p></div><span>${unassignedRows.length}</span></div><div class="unassigned-list">${unassignedRows.length ? unassignedRows.map(orphanRow).join("") : `<div class="areas-empty">All devices are assigned to an area.</div>`}</div></section>`;
    this.querySelectorAll(".areas-expand").forEach((button) => { button.onclick = () => { const details = button.nextElementSibling; const expanded = button.getAttribute("aria-expanded") === "true"; button.setAttribute("aria-expanded", String(!expanded)); details.hidden = expanded; }; });
    this.querySelector("#search").oninput = (event) => { const query = event.target.value.toLowerCase(); this.querySelectorAll("[data-search]").forEach((row) => { row.hidden = !row.dataset.search.includes(query); }); };
    this.localize();
  }

  table(module, rows) {
    const title = MODULES.find((item) => item[0] === module)?.[1] || module;
    const attention = rows.filter((item) => item.compliance_status !== "compliant").length;
    const entityPolicy = module === "entity_ids" ? `<div class="policy-banner"><b>Política auditada</b><span>O Home Assistant não expõe um padrão global. Esta análise usa a política do Organizer: <code>${escapeHtml(rows[0]?.policy || "não configurada")}</code></span></div>` : "";
    const categoryColumn = module === "categories" ? "<th>SCOPES</th>" : "";
    const columnCount = module === "categories" ? 5 : 4;
    const categoryBack = module === "categories" ? '<button class="view-switch" id="category-card-view">▦ Ver como cartões</button>' : "";
    const categoryLinks = module === "categories" ? '<a class="view-switch" href="/config/automation/dashboard">Automations ↗</a><a class="view-switch" href="/config/scene/dashboard">Scenes ↗</a><a class="view-switch" href="/config/script/dashboard">Scripts ↗</a>' : "";
    const editRoutes = { areas: "/config/areas/dashboard", zones: "/config/zone", labels: "/config/labels", exposed: "/config/voice-assistants/expose" };
    const editLink = editRoutes[module] ? `<a class="view-switch" href="${editRoutes[module]}">Edit in Home Assistant ↗</a>` : "";
    this.querySelector("#content").innerHTML = `${entityPolicy}<div class="page-heading compact"><div><div class="eyebrow">MÓDULO</div><h1>${title}</h1><p>${rows.length} itens encontrados · ${attention} pedem atenção</p></div><div class="page-actions">${editLink}${categoryLinks}${categoryBack}</div></div><div class="table-toolbar"><div class="search"><span>⌕</span><input id="search" placeholder="Buscar neste módulo…"></div><select id="status-filter"><option value="all">Todos os resultados</option><option value="compliant">Conformes</option><option value="attention">Atenção</option><option value="non_compliant">Não conformes</option><option value="stale">Desatualizados</option></select></div><div class="table-card"><table><thead><tr><th>ITEM</th>${categoryColumn}<th>RESULTADO</th><th>REVISÃO</th><th></th></tr></thead><tbody>${rows.length ? rows.map((item) => this.row(item)).join("") : `<tr><td colspan="${columnCount}"><div class="empty"><div class="empty-icon">✓</div><h3>Nenhum item neste módulo</h3><p>Ative este módulo nas configurações para iniciar uma auditoria.</p></div></td></tr>`}</tbody></table></div>`;
    const filter = () => { const query = this.querySelector("#search").value.toLowerCase(); const status = this.querySelector("#status-filter").value; this.querySelectorAll("tbody tr[data-search]").forEach((row) => { row.hidden = !row.dataset.search.includes(query) || (status !== "all" && row.dataset.status !== status && !(status === "stale" && row.dataset.review !== "stale")); }); };
    this.querySelector("#search").oninput = filter; this.querySelector("#status-filter").onchange = filter;
    if (module === "categories") this.querySelector("#category-card-view").onclick = () => { this.categories(rows); this.localize(); };
    this.localize();
    this.querySelectorAll(".review,.ignore").forEach((button) => button.onclick = async () => { const status = button.classList.contains("review") ? (button.classList.contains("reopen-action") ? "pending" : "reviewed") : "ignored"; await this.call("ha_organizer/review/set", { item_key: button.dataset.key, status, fingerprint: button.dataset.fp }); await this.show(module); });
  }

  row(item) {
    const finding = (item.findings || []).map((finding) => finding.message).join(" · ") || "Nenhuma divergência encontrada";
    const categoryInfo = item.module === "categories" ? `<td><div class="scope-list">${Object.keys(item.scopes || {}).map((scope) => { const scopeIcon = item.icons_by_scope?.[scope]; const label = scope === "automation" ? "Automations" : scope === "script" ? "Scripts" : "Scenes"; return `<span class="scope" title="${escapeHtml(scopeIcon || "No icon")}"><i>${scopeIcon ? `<ha-icon icon="${escapeHtml(scopeIcon)}"></ha-icon>` : "◌"}</i>${label}<small>${escapeHtml(scopeIcon || "No icon")}</small></span>`; }).join("") || "<span class=\"muted\">No scope</span>"}</div></td>` : "";
    const categoryVisual = item.module === "categories" ? `<span class="category-table-icon">${item.icon ? `<ha-icon icon="${escapeHtml(item.icon)}"></ha-icon>` : "⌁"}</span>` : "";
    const categoryMeta = item.module === "categories" ? `<small>${item.icon ? `Icon: ${escapeHtml(item.icon)}` : "No icon"}</small>` : "";
    const description = item.module === "labels" && item.description ? `<small>Description: ${escapeHtml(item.description)}</small>` : "";
    const labelVisual = item.module === "labels" ? `<span class="label-visual"><span class="label-icon">${item.icon ? `<ha-icon icon="${escapeHtml(item.icon)}"></ha-icon>` : "🏷"}</span><span class="label-color" style="--label-color:${safeLabelColor(item.color)}" title="${item.color ? `Color: ${escapeHtml(item.color)}` : "No color"}"></span></span>` : "";
    const labelMeta = item.module === "labels" ? `<small>${item.icon ? `Icon: ${escapeHtml(item.icon)}` : "No icon"} · ${item.color ? `Color: ${escapeHtml(item.color)}` : "No color"}</small>` : "";
    const areaMeta = item.module === "areas" ? `<small>${item.floor ? `Floor: ${escapeHtml(item.floor)}` : "No floor"} · ${(item.devices || []).length} devices · ${(item.entities || []).length} entities</small>${item.picture ? `<img class="area-picture" src="${escapeHtml(item.picture)}" alt="">` : ""}${(item.device_details || []).map((device) => `<a class="device-link" href="/config/devices/device/${encodeURIComponent(device.id)}">${escapeHtml(device.name || device.id)} ↗</a>`).join("")}` : "";
    const zoneMeta = item.module === "zones" ? `<small>Radius: ${item.radius == null ? "—" : `${escapeHtml(item.radius)} m`} · ${item.passive ? "Passive" : "Active"}</small>` : "";
    const aliases = item.module === "exposed" ? [...new Set((item.entries || []).filter((entry) => entry.name !== item.title).map((entry) => entry.name))] : [];
    const aliasInfo = aliases.length ? `<small>Aliases: ${escapeHtml(aliases.join(", "))}</small>` : "";
    const ignore = item.review_status === "ignored" ? "" : `<button class="ignore" data-key="${escapeHtml(item.item_key)}" data-fp="${item.fingerprint}">Ignore</button>`;
    const reopen = item.review_status === "reviewed";
    return `<tr data-search="${escapeHtml(`${item.title} ${item.description || ""} ${aliases.join(" ")} ${finding}`.toLowerCase())}" data-status="${escapeHtml(item.compliance_status)}" data-review="${escapeHtml(item.review_status)}"><td><div class="item-title"><span class="item-dot ${safeStatus(item.compliance_status)}"></span>${labelVisual}${categoryVisual}<div><strong>${escapeHtml(item.title)}</strong>${categoryMeta}${description}${labelMeta}${areaMeta}${zoneMeta}${aliasInfo}<small>${escapeHtml(finding)}</small></div></div></td>${categoryInfo}<td>${statusPill(item.compliance_status)}</td><td>${statusPill(item.review_status)}</td><td class="actions"><button class="review ${reopen ? "reopen-action" : "review-action"}" data-key="${escapeHtml(item.item_key)}" data-fp="${escapeHtml(item.fingerprint)}">${reopen ? "Reopen" : "Review"}</button>${ignore}</td></tr>`;
  }
}

const safeStatus = (status) => ["compliant", "non_compliant", "attention", "pending", "reviewed", "ignored", "stale"].includes(status) ? status : "pending";
const safeLabelColor = (color) => { const value = String(color || "").toLowerCase(); const palette = { primary: "var(--primary-color)", accent: "var(--accent-color)", red: "#f44336", pink: "#e91e63", purple: "#9c27b0", indigo: "#3f51b5", blue: "#2196f3", cyan: "#00bcd4", teal: "#009688", green: "#4caf50", lime: "#cddc39", yellow: "#fbc02d", orange: "#ff9800", brown: "#795548", grey: "#9e9e9e", gray: "#9e9e9e" }; return /^#[0-9a-f]{6}$/i.test(value) ? value : (palette[value] || "#d8deea"); };
const bar = (name, value, total, color) => `<div class="bar-row"><div><span>${escapeHtml(name)}</span><b>${escapeHtml(value)} (${Number(total) ? Math.round(Number(value) / Number(total) * 100) : 100}%)</b></div><div class="bar"><i class="${["green", "orange", "red", "purple", "gray"].includes(color) ? color : "gray"}" style="width:${Math.min(Math.max(Number(total) ? Math.max(Number(value) / Number(total) * 100, Number(value) ? 3 : 0) : 0, 0), 100)}%"></i></div></div>`;
const statusPill = (status) => { const labels = { compliant: "Conforme", non_compliant: "Não conforme", attention: "Atenção", pending: "Pendente", reviewed: "Revisado", ignored: "Ignorado", stale: "Desatualizado" }; const safe = safeStatus(status); return `<span class="pill ${safe}"><i></i>${escapeHtml(labels[status] || "Unknown status")}</span>`; };
const escapeHtml = (value) => String(value).replace(/[&<>"']/g, (char) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[char]);
